def broadcastTime(manager, informTime):
    n = len(manager)
    subs = [[] for _ in range(n)]
    head = 0
    for e, m in enumerate(manager):
        if m == -1:
            head = e
        else:
            subs[m].append(e)
    best = 0
    stack = [(head, 0)]
    while stack:
        e, t = stack.pop()
        if t > best:
            best = t
        for s in subs[e]:
            stack.append((s, t + informTime[e]))
    return best
